scripts.script:
local OrionLib = loadstring(game:HttpGet(('https://raw.githubusercontent.com/shlexware/Orion/main/source')))()
local Window = OrionLib:MakeWindow({Name = "🎩 MR RED BLACK GUI🎩", HidePremium = false, SaveConfig = true, ConfigFolder = "OrionTest"})

local HouseTab = Window:MakeTab({
    Name = "HOUSE",
    Icon = "rbxassetid://4483345998",
    PremiumOnly = false
})

local BodyTab = Window:MakeTab({
    Name = "BODY/CORPO",
    Icon = "rbxassetid://4483345998",
    PremiumOnly = false
})

HouseTab:AddTextbox({
    Name = "Player Nick",
    Default = "",
    TextDisappear = false,
    Callback = function(value)
        playerNick = value
    end
})

HouseTab:AddButton({
    Name = "FLY GUI",
    Callback = function()
        loadstring(game:HttpGet("https://rawscripts.net/raw/Universal-Script-Fly-Gui-V4-25042"))()
    end    
})

HouseTab:AddButton({
    Name = "CLEITIN",
    Callback = function()
        loadstring(game:HttpGet("https://rawscripts.net/raw/Brookhaven-RP-CLEITI6966-HUBS-22818"))()
    end    
})

HouseTab:AddButton({
    Name = "o escuro",
    Callback = function()
        loadstring(game:HttpGet("https://rawscripts.net/raw/Brookhaven-RP-The-Darkones-24927"))()
    end    
})

HouseTab:AddButton({
    Name = "DISCORD GRUPO",
    Callback = function()
        setclipboard("https://discord.gg/fuF6DpVJ")
        OrionLib:MakeNotification({
            Name = "Link Copiado!",
            Content = "O link do Discord foi copiado para a área de transferência.",
            Image = "rbxassetid://4483345998",
            Time = 5
        })
    end    
})

HouseTab:AddButton({
    Name = "R4D",
    Callback = function()
        loadstring(game:HttpGet("https://rawscripts.net/raw/Brookhaven-RP-R4D-TROLL-NO-KEY-17625"))()
    end    
})

-- Adicionando o botão "SCRIPT DE CORPO BASICO" na aba "BODY/CORPO"
BodyTab:AddButton({
    Name = "SCRIPT DE CORPO BASICO",
    Callback = function()
        loadstring(game:HttpGet("https://rawscripts.net/raw/Universal-Script-script-universal-basico-25153"))()
    end    
})

OrionLib:Init()

local args = {
    [1] = "Morph",
    [2] = "s3",
    [3] = 350
}

game:GetService("ReplicatedStorage"):WaitForChild("Morphing2"):FireServer(unpack(args))
